export const transactionsQueryKey = (options: Options<TransactionsData>) => createQueryKey('transactions', options, false, ['Wallet Resource']);

/**
 * Transactions
 */
export const transactionsOptions = (options: Options<TransactionsData>) => queryOptions<TransactionsResponse, DefaultError, TransactionsResponse, ReturnType<typeof transactionsQueryKey>>({
    queryFn: async ({ queryKey, signal }) => {
        const { data } = await transactions({
            ...options,
            ...queryKey[0],
            signal,
            throwOnError: true
        });
        return data;
    },
    queryKey: transactionsQueryKey(options)
});

const createInfiniteParams = <K extends Pick<QueryKey<Options>[0], 'body' | 'headers' | 'path' | 'query'>>(queryKey: QueryKey<Options>, page: K) => {
    const params = { ...queryKey[0] };
    if (page.body) {
        params.body = {
            ...queryKey[0].body as any,
            ...page.body as any
        };
    }
    if (page.headers) {
        params.headers = {
            ...queryKey[0].headers,
            ...page.headers
        };
    }
    if (page.path) {
        params.path = {
            ...queryKey[0].path as any,
            ...page.path as any
        };
    }
    if (page.query) {
        params.query = {
            ...queryKey[0].query as any,
            ...page.query as any
        };
    }
    return params as unknown as typeof page;
};

export const transactionsInfiniteQueryKey = (options: Options<TransactionsData>): QueryKey<Options<TransactionsData>> => createQueryKey('transactions', options, true);

/**
 * Transactions
 */
export const transactionsInfiniteOptions = (options: Options<TransactionsData>) => infiniteQueryOptions<TransactionsResponse, DefaultError, InfiniteData<TransactionsResponse>, QueryKey<Options<TransactionsData>>, number | Pick<QueryKey<Options<TransactionsData>>[0], 'body' | 'headers' | 'path' | 'query'>>(
// @ts-ignore
{
    queryFn: async ({ pageParam, queryKey, signal }) => {
        // @ts-ignore
        const page: Pick<QueryKey<Options<TransactionsData>>[0], 'body' | 'headers' | 'path' | 'query'> = typeof pageParam === 'object' ? pageParam : {
            query: {
                offset: pageParam
            }
        };
        const params = createInfiniteParams(queryKey, page);
        const { data } = await transactions({
            ...options,
            ...params,
            signal,
            throwOnError: true
        });
        return data;
    },
    queryKey: transactionsInfiniteQueryKey(options)
});

/**
 * Transactions
 */
export const useTransactionsQuery = (options: Options<TransactionsData>) => useQuery(transactionsOptions(options));
